// Class definition
class Car {
    // Attributes (fields)
    String color;
    int speed;

    // Behavior (method)
    void drive() {
        System.out.println("The " + color + " car is driving at " + speed + " mph.");
    }
}

public class Main {
    public static void main(String[] args) {
        // Creating an Object of the Car class
        Car myCar = new Car(); 

        // Setting state/attributes
        myCar.color = "Red";
        myCar.speed = 60;

        // Calling method
        myCar.drive(); // Output: The Red car is driving at 60 mph.
    }
}
